<script setup>import {state,actions,displayTime} from '../../domain/prototypeStore.js'</script>
<template><section class="page-stack"><div class="page-heading"><div class="module-icon">卡</div><div><h2>打卡管理</h2><p>打卡规则、二维码、记录和异常处置</p></div><button class="secondary-button" @click="actions.detectAttendanceException()">检查异常</button></div><article class="panel"><h3>{{state.checkinRules.group}} · {{state.checkinRules.point}}</h3><p>有效时间：{{state.checkinRules.time}}　有效范围：{{state.checkinRules.radius}}</p><div class="qr-placeholder">演示二维码<br><small>用于移动端打卡演示</small></div></article><article class="panel"><h3>异常提醒</h3><div v-for="a in state.attendanceAlerts" :key="a.id" class="alert-row"><span>{{a.type}} · {{a.person}} · {{a.status}}</span><div><button v-if="a.status==='待处理'" class="secondary-button" @click="actions.retryAttendance(a.id)">联系跟进</button><button v-if="a.status!=='已处理'" class="secondary-button" @click="actions.resolveAttendance(a.id)">标记已处理</button></div></div></article><div class="table-card"><table><thead><tr><th>人员</th><th>时间</th><th>结果</th><th>说明</th></tr></thead><tbody><tr v-for="r in state.checkins" :key="r.id"><td>{{r.person}}</td><td>{{displayTime(r.time)}}</td><td>{{r.status}}</td><td>{{r.reason}}</td></tr></tbody></table></div></section></template>
